INSERT INTO productos (id, tipo, ruta, estado, titulo, titular, descripcion, multimedia, detalles, precio, stock, portada, vistas, ventas, vistasGratis, ventasGratis, ofertadoPorCategoria, ofertadoPorSubCategoria, oferta, precioOferta, descuentoOferta, imgOferta, finOferta, peso, entrega, costo_envio, categoria_id, subcategoria_id, marca_id, proveedor_id, fecha) VALUES (166, 'fisico', 'nibs-de-cacao-mono-tingales-150-gr', 1, 'NIBS DE CACAO MONO TINGALES 150 GR', 'Nuestros Nibs de Cacao son trozos de cacao tostado y triturado, capturando la esencia pura y crujiente de la semilla del cacao. Cada bocado revela una explosi├│n de sabores que incluyen notas intensas de chocolate puro, con s...', 'Nuestros Nibs de Cacao son trozos de cacao tostado y triturado, capturando la esencia pura y crujiente de la semilla del cacao. Cada bocado revela una explosión de sabores que incluyen notas intensas de chocolate puro, con sutiles matices de frutas y nueces. Agrega un toque crujiente a tus batidos, yogures o ensaladas, o úsalos como ingrediente clave en la elaboración de postres gourmet. Su versatilidad culinaria te invita a experimentar y elevar tus creaciones gastronómicas a nuevas alturas.', '[\"productos/multimedia/nibs-de-cacao-mono-tingales-150-gr/chocolate-nibs.jpg\"]', '{\"Talla\":[],\"Color\":[],\"Marca\":[\"Mono Tingales\"]}', 8.5, 0, 'productos/portadas/nibs-de-cacao-mono-tingales-150-gr.jpg', 1427, 274, 0, 0, 0, 0, 0, 0, 0, '', '0000-00-00 00:00:00', 0, 0, NULL, 88, 157, 11, NULL, '2026-07-27 12:16:45') ON DUPLICATE KEY UPDATE tipo = 'fisico', ruta = 'nibs-de-cacao-mono-tingales-150-gr', estado = 1, titulo = 'NIBS DE CACAO MONO TINGALES 150 GR', titular = 'Nuestros Nibs de Cacao son trozos de cacao tostado y triturado, capturando la esencia pura y crujiente de la semilla del cacao. Cada bocado revela una explosi├│n de sabores que incluyen notas intensas de chocolate puro, con s...', descripcion = 'Nuestros Nibs de Cacao son trozos de cacao tostado y triturado, capturando la esencia pura y crujiente de la semilla del cacao. Cada bocado revela una explosión de sabores que incluyen notas intensas de chocolate puro, con sutiles matices de frutas y nueces. Agrega un toque crujiente a tus batidos, yogures o ensaladas, o úsalos como ingrediente clave en la elaboración de postres gourmet. Su versatilidad culinaria te invita a experimentar y elevar tus creaciones gastronómicas a nuevas alturas.', multimedia = '[\"productos/multimedia/nibs-de-cacao-mono-tingales-150-gr/chocolate-nibs.jpg\"]', detalles = '{\"Talla\":[],\"Color\":[],\"Marca\":[\"Mono Tingales\"]}', precio = 8.5, stock = 0, portada = 'productos/portadas/nibs-de-cacao-mono-tingales-150-gr.jpg', vistas = 1427, ventas = 274, vistasGratis = 0, ventasGratis = 0, ofertadoPorCategoria = 0, ofertadoPorSubCategoria = 0, oferta = 0, precioOferta = 0, descuentoOferta = 0, imgOferta = '', finOferta = '0000-00-00 00:00:00', peso = 0, entrega = 0, costo_envio = NULL, categoria_id = 88, subcategoria_id = 157, marca_id = 11, proveedor_id = NULL, fecha = '2026-07-27 12:16:45';
